let LANG = 'ro';
function setLang(l) {
  LANG = I18N[l] ? l : 'ro';
  document.documentElement.lang = LANG;
}
function t(key, vars) {
  let s = (I18N[LANG] && I18N[LANG][key]) ?? I18N.ro[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split('{' + k + '}').join(String(v));
  return s;
}
